#!/usr/bin/env bash
# Generated by Confys Local. Creates the local environment from scratch:
# minikube cluster, ArgoCD (pinned), the service images, and the root ArgoCD Application.
set -euo pipefail
cd "$(dirname "$0")/.."

PROFILE=onboarding
ARGOCD_VERSION=v3.6.3

need() { command -v "$1" >/dev/null 2>&1 || { echo "Missing prerequisite: $1" >&2; exit 1; }; }
for tool in docker minikube kubectl git mvn; do need "$tool"; done
docker info >/dev/null 2>&1 || { echo "Docker is not running" >&2; exit 1; }

minikube start -p "$PROFILE" --driver=docker --cpus=3 --memory=4g
kubectl config use-context "$PROFILE"

kubectl create namespace argocd --dry-run=client -o yaml | kubectl apply -f -
kubectl apply -n argocd --server-side --force-conflicts \
  -f "https://raw.githubusercontent.com/argoproj/argo-cd/${ARGOCD_VERSION}/manifests/install.yaml"
kubectl -n argocd rollout status deploy/argocd-server --timeout=300s

# Images first: a tag pinned in Git must exist in the cluster before ArgoCD deploys it.
for service in service-b service-a; do
  scripts/release.sh "$service" --load-only
done

kubectl apply -n argocd -f deploy/argocd/root.yaml
echo "Environment is up. ArgoCD syncs from https://github.com/romanFrontEnd/onboarding-app.git (revision main)."
echo "Check with: make status    Call service-a with: make forward"
